// BAD — causes multiple reflows (slow)
const box = document.getElementById('box');
box.style.width = '100px';   // triggers reflow
box.style.height = '100px';  // triggers reflow again
box.style.color = 'red';     // triggers repaint again

// GOOD — batch DOM changes using a class (one reflow)
box.classList.add('resized-red-box');

