// HTTP GET request — retrieve a user
// Method: GET | URL: /api/users/42 | Body: none
fetch('https://api.example.com/users/42')
  .then(res => res.json())
  .then(user => console.log(user));

// HTTP POST request — create a new user  
// Method: POST | URL: /api/users | Body: JSON
fetch('https://api.example.com/users', {
  method: 'POST',
  headers: { 'Content-Type': 'application/json' },
  body: JSON.stringify({ name: 'Sara', email: 'sara@example.com' })
})
  .then(res => res.json())
  .then(newUser => console.log(newUser)); // { id: 43, name: 'Sara', ... }

// You will encounter errors like this hundreds of times
// TypeError: Cannot read properties of undefined (reading 'name')

